with scam as (insert into public.practice_scams(stable_code,name,category) values('delivery-redelivery-fee','Parcel redelivery fee','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 1, 'Your parcel is on hold: action needed', 'Dear Customer,

We attempted to deliver your parcel today but no one was available to sign for it. Your parcel is now on hold at our depot.

To schedule a new delivery, please pay the $1.99 redelivery fee within 24 hours:
{link}

If the fee is not paid, your parcel will be returned to the sender.

Parcel Delivery Services', 'Fees by email for redelivery are a common way to collect card numbers.', array['A real delivery notice usually has your name or a tracking number on it.','Delivery companies don''t charge a fee by email to try again. The small amount is there to get your card number.','The deadline is there to hurry you past the moment where you''d stop and wonder.']::text[], 'Fake delivery notices are one of the most common scams going, because almost everyone has a parcel on the way at some point. The fee is small on purpose. The goal is your card number, and once they have it, the charges are a lot larger than $1.99.', 'draft', '[{"quote":"Dear Customer","note":"A real delivery notice usually has your name or a tracking number on it."},{"quote":"$1.99 redelivery fee","note":"Delivery companies don''t charge a fee by email to try again. The small amount is there to get your card number."},{"quote":"within 24 hours","note":"The deadline is there to hurry you past the moment where you''d stop and wonder."}]'::jsonb, '{"from_name":"Parcel Delivery Notice","from_local":"delivery-notice"}'::jsonb, 'generic', null, 'human', array['If I''m expecting something, I''ll look up the tracking number on the shop''s own website.','I won''t put my card details into a link that came in an email.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to pay a fee by email to get a parcel redelivered","The email arriving in the afternoon","The parcel being held at a depot"],"correct":0,"affirm":"That''s right. A delivery company won''t email you asking for a fee to try again, so that request on its own is enough to delete it.","gently":"That one''s understandable, but the clearest sign is the fee. A delivery company won''t email you asking for money to try again, so that request on its own is enough to delete it."}'::jsonb, '/scam-alerts/scams-targeting-seniors-2026'
