with scam as (insert into public.practice_scams(stable_code,name,category) values('utility-shutoff-today','Power shut-off today','utility') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 2, 'Final notice: service disconnection scheduled for today', 'FINAL DISCONNECTION NOTICE

Our records show your account is past due by $186.42. Your electric service is scheduled to be disconnected today at 4:00 PM.

To avoid disconnection, payment must be made immediately. We accept payment by prepaid gift card or through our secure payment portal:
{link}

To stop the disconnection, do not contact your local office. Use only the link above.

Utility Billing Department', 'Same-day shut-off threats and gift card payments are utility scam signs.', array['Utilities send several notices by post over weeks before any shut-off. Same-day warnings by email are made up.','No utility takes gift cards. When someone asks for one, it''s a scam every time.','Telling you not to check is the clearest sign they know checking would expose them.']::text[], 'Utility scams lean on a real fear, sitting in the dark or the cold. Real utilities give plenty of written notice and take ordinary payments. A demand to pay today, by gift card, without checking with anyone, is three warning signs in one.', 'draft', '[{"quote":"scheduled to be disconnected today at 4:00 PM","note":"Utilities send several notices by post over weeks before any shut-off. Same-day warnings by email are made up."},{"quote":"prepaid gift card","note":"No utility takes gift cards. When someone asks for one, it''s a scam every time."},{"quote":"do not contact your local office","note":"Telling you not to check is the clearest sign they know checking would expose them."}]'::jsonb, '{"from_name":"Utility Billing Department","from_local":"billing-dept"}'::jsonb, 'generic', null, 'human', array['I''ll call the number on my last paper bill and ask about my account.','I''ll never pay a bill with a gift card.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The exact dollar amount","Being told not to contact your local office","The 4:00 PM time"],"correct":1,"affirm":"Right. A real company never tells you not to check with them, so that line gives the whole thing away.","gently":"The exact amount is meant to look official, which is clever. The surest sign is being told not to contact your local office. A real company would never say that."}'::jsonb, null
