with scam as (insert into public.practice_scams(stable_code,name,category) values('jury-duty-warrant','Missed jury duty fine','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 2, 'Notice of failure to appear for jury duty', 'NOTICE OF FAILURE TO APPEAR

Our records indicate that you did not report for jury duty as summoned. A bench warrant may be issued for your arrest.

You can resolve this matter today by paying a fine of $495. Once paid, the warrant will be cancelled.

Pay your fine securely here:
{link}

Failure to respond within 24 hours will result in further legal action.

County Court Services, Jury Division', 'Courts don''t threaten arrest or collect fines by email.', array['Courts don''t threaten arrest by email. A missed summons is handled by post and in person.','Courts don''t collect fines through email links, and paying never cancels a warrant.','The short deadline is there to scare you into paying before you call anyone.']::text[], 'Jury duty scams work on worry and embarrassment. Nobody wants to be in trouble with a court, so people pay quickly and quietly. A real court would never ask for payment to cancel a warrant, and you can always call the clerk''s office yourself to check.', 'draft', '[{"quote":"A bench warrant may be issued for your arrest","note":"Courts don''t threaten arrest by email. A missed summons is handled by post and in person."},{"quote":"paying a fine of $495","note":"Courts don''t collect fines through email links, and paying never cancels a warrant."},{"quote":"within 24 hours","note":"The short deadline is there to scare you into paying before you call anyone."}]'::jsonb, '{"from_name":"County Court Services","from_local":"court-services"}'::jsonb, 'generic', null, 'human', array['I''ll look up the court''s number myself and call to ask.','I won''t pay any fine from an email link.','I''ll tell someone in the family, because these scams count on embarrassment.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to pay a fine to cancel an arrest warrant","The words ''Jury Division''","The email having a subject line"],"correct":0,"affirm":"Yes. Courts don''t take payments by email to make a warrant go away, so that offer gives it away.","gently":"Official-sounding names are part of the disguise. The clearest sign is the payment: courts don''t take money by email to make a warrant go away."}'::jsonb, '/scam-alerts/scams-targeting-seniors-2026'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('family-new-email','"It''s me" from a new address','family_emergency') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 2, 'It''s me, I lost my phone', 'Hi, it''s me. I lost my phone and I''m using a friend''s email for now, so don''t use my old number.

I''m in a bit of trouble and I really need your help. I need to pay something today and my cards aren''t working. Can you send $600? I''ll pay you back as soon as I sort this out.

Please don''t tell Mom or Dad yet, I''ll explain everything later.

Here''s where you can send it:
{link}

Thank you so much, I love you.', '"It''s me" messages from a new address asking for urgent, secret money are family emergency scams.', array['Someone you know would use their name. ''It''s me'' lets you fill in who you think it is.','This stops you from calling them back to check, which is exactly what you should do.','Asking you to keep it secret keeps you from hearing that they''re perfectly fine.']::text[], 'This is the email version of the grandparent scam. It works because it lands on love and worry at the same time. The details that make it effective, a new address, a secret, a deadline, are the same ones that give it away. Calling the number you already have settles it in a minute.', 'draft', '[{"quote":"Hi, it''s me","note":"Someone you know would use their name. ''It''s me'' lets you fill in who you think it is."},{"quote":"don''t use my old number","note":"This stops you from calling them back to check, which is exactly what you should do."},{"quote":"Please don''t tell Mom or Dad yet","note":"Asking you to keep it secret keeps you from hearing that they''re perfectly fine."}]'::jsonb, '{"from_name":"Me (new email)","from_local":"its-me"}'::jsonb, 'generic', null, 'human', array['I''ll call them on the number I already have, whatever the message says.','If I can''t reach them, I''ll call someone else in the family before I send anything.','I won''t send money to a link or a new account because of a message.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The message says ''I love you''","It asks you not to use their old number and to keep it secret","It asks for $600 instead of a larger amount"],"correct":1,"affirm":"Exactly. Being steered away from calling them and from telling the family is how these scams keep you from finding out the truth.","gently":"The amount can feel reassuring, which is part of the trick. The clearest sign is being steered away from calling them and from telling the family."}'::jsonb, '/scam-alerts/ai-voice-cloning-grandparent-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('charity-disaster-match','Disaster relief with a matching deadline','charity') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 2, 'Families need you tonight: donations matched until midnight', 'Dear Friend,

Thousands of families lost everything in this week''s storms. Tonight, every dollar you give will be DOUBLED by a generous donor, but only until midnight.

Please give $50, $100 or whatever you can. Donations by gift card or wire transfer reach families fastest.

Give now:
{link}

With gratitude,
The Disaster Relief Fund', 'Fake charities use deadlines and untraceable payment methods.', array['Real charities welcome donations any time. A countdown is there to stop you from looking the charity up first.','Established charities take cards and checks. Gift cards and wires can''t be traced or refunded.','A charity you''ve given to before would know your name.']::text[], 'Fake charities show up after every disaster because generous people want to help quickly. Giving through a charity you already know, on its own website, gets your money to the people who need it.', 'draft', '[{"quote":"only until midnight","note":"Real charities welcome donations any time. A countdown is there to stop you from looking the charity up first."},{"quote":"Donations by gift card or wire transfer","note":"Established charities take cards and checks. Gift cards and wires can''t be traced or refunded."},{"quote":"Dear Friend","note":"A charity you''ve given to before would know your name."}]'::jsonb, '{"from_name":"Disaster Relief Fund","from_local":"relief"}'::jsonb, 'generic', null, 'human', array['I''ll give to a charity I already know, by going to its website myself.','I''ll look up any charity I don''t know before giving.','I won''t give by gift card or wire.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Mentioning storms in the news","Asking for gift cards or wire transfers","Suggesting amounts like $50 or $100"],"correct":1,"affirm":"Yes. Real charities don''t ask for gift cards or wires, so that''s the clearest sign.","gently":"Mentioning real news is what makes these convincing. The clearest sign is the payment method: real charities don''t ask for gift cards or wires."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('medicare-plan-change','Medicare plan ending','medicare') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Important: changes to your Medicare coverage for 2027', 'Dear Beneficiary,

During this year''s Open Enrollment period, your current plan has been flagged for changes that may affect your coverage starting January 1.

To avoid a gap in coverage, please review and confirm your plan within 48 hours. You will need your Medicare number to continue.

Review your coverage:
{link}

If you have already reviewed your plan, you may ignore this message.

Medicare Benefits Office
Beneficiary Services', 'Medicare doesn''t email asking for your Medicare number, and Open Enrollment deadlines aren''t 48 hours.', array['Open Enrollment runs for weeks. Nobody official gives you 48 hours to act.','Your Medicare number is valuable to scammers, who use it to bill for things you never got. Keep it for your doctors and pharmacy.','Medicare doesn''t email you to ask for your number. If something needed checking, you''d get a letter.']::text[], 'This one is harder because it arrives during real Open Enrollment, when you''re expecting mail about your plan. The polite last line (''you may ignore this message'') makes it feel routine. What gives it away is the short deadline and the request for your Medicare number.', 'draft', '[{"quote":"within 48 hours","note":"Open Enrollment runs for weeks. Nobody official gives you 48 hours to act."},{"quote":"You will need your Medicare number to continue","note":"Your Medicare number is valuable to scammers, who use it to bill for things you never got. Keep it for your doctors and pharmacy."},{"quote":"Medicare Benefits Office","note":"Medicare doesn''t email you to ask for your number. If something needed checking, you''d get a letter."}]'::jsonb, '{"from_name":"Medicare Benefits Office","from_local":"benefits"}'::jsonb, 'generic', '2026-12-08'::timestamptz, 'human', array['I''ll call the number on my Medicare card, or 1-800-MEDICARE, if I want to check my plan.','I won''t type my Medicare number into a link from an email.','I''ll review plans with someone I trust, like a local SHIP counselor.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions Open Enrollment","It asks for your Medicare number with a 48-hour deadline","It says you may ignore it"],"correct":1,"affirm":"That''s right. A short deadline plus a request for your Medicare number is the combination to watch for.","gently":"It does feel more trustworthy because it mentions the real Open Enrollment. The giveaway is the 48-hour deadline and the request for your Medicare number."}'::jsonb, '/scam-alerts/medicare-open-enrollment-scams'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('tax-refund-pending','Tax refund waiting','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'You have a pending tax refund of $1,284.00', 'Hello,

After a review of your recent tax filing, we have determined that you are eligible for an additional refund of $1,284.00.

To receive your refund by direct deposit, please confirm your bank account details and Social Security number using the secure form below:
{link}

Refunds not claimed within 5 business days will be returned to the Treasury.

Tax Refund Department
Taxpayer Services', 'The tax agency doesn''t email about refunds or ask for your Social Security number by email.', array['The tax agency contacts people by post, not by email, and certainly not to hand out surprise money.','These two together are what someone needs to take over your accounts or file a return in your name.','A refund you''re owed doesn''t vanish because you didn''t click quickly.']::text[], 'A refund email is pleasant to get, which is why it works better than a threat for some people. Good news can lower your guard. The request for your bank details and Social Security number is what to notice.', 'draft', '[{"quote":"eligible for an additional refund of $1,284.00","note":"The tax agency contacts people by post, not by email, and certainly not to hand out surprise money."},{"quote":"your bank account details and Social Security number","note":"These two together are what someone needs to take over your accounts or file a return in your name."},{"quote":"within 5 business days","note":"A refund you''re owed doesn''t vanish because you didn''t click quickly."}]'::jsonb, '{"from_name":"Tax Refund Department","from_local":"refunds"}'::jsonb, 'generic', null, 'human', array['If I think I''m owed a refund, I''ll check on the tax agency''s website by typing the address myself.','I''ll never send my Social Security number in reply to an email.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The refund amount","Being asked for your bank details and Social Security number by email","The word ''Treasury''"],"correct":1,"affirm":"Yes. Nobody official asks for your Social Security number and bank details through an email link.","gently":"The exact amount is there to seem believable. The clearest sign is the request for your Social Security number and bank details, which nobody official asks for by email."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('subscription-renewal-refund','Surprise renewal charge','tech_support') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Receipt: your annual protection plan has renewed ($399.99)', 'Thank you for your purchase.

Your annual Device Protection Plan has been renewed automatically.

Amount charged: $399.99
Payment method: card on file
Renewal period: 12 months

If you did not authorize this renewal, you have 24 hours to request a refund. To cancel and receive your refund, open your billing page:
{link}

Billing Support Team', 'Fake renewal receipts push you to ''cancel'' through a scammer.', array['If you don''t recognize the plan, that''s because there isn''t one. The surprise is meant to send you straight to the link.','The rush makes you act before checking your actual bank or card statement.','The ''refund'' is the trap. These scams end with someone on your computer ''fixing'' an overpayment from your bank account.']::text[], 'Fake receipts are clever because they make you want to act to protect yourself. The urge to get your money back is what sends people to the link or phone number. Your real statement will tell you whether anything was charged.', 'draft', '[{"quote":"Your annual Device Protection Plan","note":"If you don''t recognize the plan, that''s because there isn''t one. The surprise is meant to send you straight to the link."},{"quote":"you have 24 hours to request a refund","note":"The rush makes you act before checking your actual bank or card statement."},{"quote":"To cancel and receive your refund","note":"The ''refund'' is the trap. These scams end with someone on your computer ''fixing'' an overpayment from your bank account."}]'::jsonb, '{"from_name":"Billing Support","from_local":"billing"}'::jsonb, 'generic', null, 'human', array['I''ll check my bank or card statement directly to see if there''s really a charge.','If I see a charge I don''t recognize, I''ll call the number on the back of my card.','I won''t call or click anything in a receipt I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A receipt for a plan you never bought, pushing you to cancel within 24 hours","The word ''receipt''","The amount ending in .99"],"correct":0,"affirm":"Right. A charge you don''t recognize with a short refund window is the setup, and checking your own statement takes the sting out of it.","gently":"Prices ending in .99 are common in real receipts too. The clearest sign is a charge for something you never bought, paired with a rush to ''cancel''."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('romance-wrong-address','Friendly stranger with photos','romance') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'I think I have the wrong email, sorry!', 'Hello,

I''m so sorry, I think I have written to the wrong address. I was trying to reach an old friend from my time in the service. I hope I am not bothering you.

You seem like a kind person, and to be honest it has been a lonely year since I lost my wife. I am working overseas on an engineering contract right now.

If you would like to talk, I would enjoy that very much. Here are some photos from where I am working:
{link}

Warm wishes,
Daniel', '"Wrong address" openers from lonely, overseas strangers are how romance scams begin.', array['The ''wrong address'' opener is a way to start a conversation with a stranger without looking like a sales pitch.','Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams.','Working abroad explains why they can never meet or video call, and later why they need money sent.']::text[], 'Romance scams start slowly and kindly, and money doesn''t come up for weeks or months. That''s why the opening is the best place to spot them. A stranger who writes ''by mistake'', shares a loss and lives somewhere far away fits a pattern scammers follow closely.', 'draft', '[{"quote":"I think I have written to the wrong address","note":"The ''wrong address'' opener is a way to start a conversation with a stranger without looking like a sales pitch."},{"quote":"it has been a lonely year since I lost my wife","note":"Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams."},{"quote":"working overseas on an engineering contract","note":"Working abroad explains why they can never meet or video call, and later why they need money sent."}]'::jsonb, '{"from_name":"Daniel","from_local":"daniel.w"}'::jsonb, 'generic', null, 'human', array['I won''t reply to messages from strangers who wrote to me ''by mistake''.','I won''t click photos or links from someone I don''t know.','If I do start talking to someone online, I''ll never send money to a person I haven''t met.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["He says he''s sorry","A stranger writing ''by mistake'', sharing a loss and working overseas","He signs off with ''Warm wishes''"],"correct":1,"affirm":"Yes. That opening pattern is how these scams usually start, long before money comes up.","gently":"Politeness is part of the charm, so it''s easy to warm to. The pattern to notice is the ''wrong address'' start, the quick sharing of a loss, and the job overseas."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('voter-registration-problem','Voter registration problem','election') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Action required: issue with your voter registration', 'Dear Voter,

During a routine review of voter rolls, we found a problem with your registration that may prevent you from voting in the upcoming election.

To keep your registration active, please confirm your identity, including your date of birth and the last four digits of your Social Security number, before the deadline:
{link}

Registrations that are not confirmed may be removed from the rolls.

Election Records Office
Voter Services Division', 'Election offices don''t email asking for your Social Security number to keep you registered.', array['Election offices send problems by post, and you can always check your own registration on your state''s official website.','Nobody needs your Social Security number by email to keep you registered.','The threat of losing your vote is meant to make you act fast.']::text[], 'Election-season scams pick up in the weeks before a vote, when people care most about being able to take part. You can check your own registration on your state''s website in a couple of minutes, which is much safer than any link.', 'draft', '[{"quote":"we found a problem with your registration","note":"Election offices send problems by post, and you can always check your own registration on your state''s official website."},{"quote":"the last four digits of your Social Security number","note":"Nobody needs your Social Security number by email to keep you registered."},{"quote":"may be removed from the rolls","note":"The threat of losing your vote is meant to make you act fast."}]'::jsonb, '{"from_name":"Election Records Office","from_local":"voter-records"}'::jsonb, 'generic', '2026-11-04'::timestamptz, 'human', array['I''ll check my registration on my state''s official election website by typing it in myself.','I''ll call my county election office if I''m unsure.','I won''t give personal details through an email link.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The email mentions the upcoming election","It asks for part of your Social Security number by email","It calls you ''Dear Voter''"],"correct":1,"affirm":"Right. No election office asks for your Social Security number through an email link.","gently":"The timing makes it feel real, which is why it works. The clearest sign is the request for your Social Security number, which no election office makes by email."}'::jsonb, '/scam-alerts/weekly-2026-10-19'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('benefits-suspended','Benefits suspended','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Your benefits have been suspended', 'Notice of Suspension

Your monthly benefits have been suspended due to suspicious activity linked to your Social Security number.

To reinstate your benefits and avoid a permanent hold, you must verify your identity today. A case officer has been assigned to your file.

Verify and speak with your case officer:
{link}

Case reference: BA-2207-44

Benefits Administration
Office of Inspector Services', 'Benefits aren''t suspended by email, and Social Security numbers can''t be suspended.', array['Your number can''t be ''suspended'', and benefits aren''t stopped by email.','The ''case officer'' is the scammer. The official-sounding role is there to make you trust them.','A reference number makes it look official. Anyone can make one up.']::text[], 'Government impersonation scams take a real worry, losing income you rely on, and attach official-sounding details to it. The reference number and the case officer are props. A call to the agency on a number you looked up yourself clears it up.', 'draft', '[{"quote":"suspended due to suspicious activity linked to your Social Security number","note":"Your number can''t be ''suspended'', and benefits aren''t stopped by email."},{"quote":"A case officer has been assigned to your file","note":"The ''case officer'' is the scammer. The official-sounding role is there to make you trust them."},{"quote":"Case reference: BA-2207-44","note":"A reference number makes it look official. Anyone can make one up."}]'::jsonb, '{"from_name":"Benefits Administration","from_local":"benefits-admin"}'::jsonb, 'generic', null, 'human', array['I''ll call the agency on a number I look up myself.','I''ll check my benefits by signing in to the official website the usual way.','I won''t call a ''case officer'' named in an email.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The case reference number","A claim that your benefits were suspended by email over your Social Security number","The word ''Inspector''"],"correct":1,"affirm":"Yes. Benefits aren''t suspended by email, so the claim itself gives it away.","gently":"The reference number is there to make it feel official. The real giveaway is the claim itself: benefits aren''t suspended by email."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('customs-duty-package','Customs fee on a package','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'Customs clearance required for your shipment', 'Hello,

A package addressed to you is being held at customs pending payment of import duties.

Shipment ID: 7740-2219-US
Duty owed: $12.60

Please pay the duty within 3 days to release your package. After that, it will be returned to the sender and a storage fee will apply.

Pay customs duty:
{link}

International Shipping Customs
Clearance Department', 'Surprise customs fees by email are a variation on the delivery fee scam.', array['If you ordered from abroad, the shop or carrier tells you about duties at checkout or on delivery, not in a surprise email.','A small, exact amount feels routine. The real aim is your card number.','Adding a penalty is another way to hurry you.']::text[], 'This is a close cousin of the redelivery fee scam, dressed up with a shipment ID to look official. Most people don''t know how customs fees work, which is what makes it believable.', 'draft', '[{"quote":"being held at customs pending payment of import duties","note":"If you ordered from abroad, the shop or carrier tells you about duties at checkout or on delivery, not in a surprise email."},{"quote":"Duty owed: $12.60","note":"A small, exact amount feels routine. The real aim is your card number."},{"quote":"a storage fee will apply","note":"Adding a penalty is another way to hurry you."}]'::jsonb, '{"from_name":"International Shipping Customs","from_local":"customs"}'::jsonb, 'generic', null, 'human', array['I''ll check the order on the shop''s own website if I''m expecting something.','I won''t pay a customs fee from an email link.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The shipment ID number","A surprise email asking you to pay a customs fee through a link","The package going back to the sender"],"correct":1,"affirm":"Right. A surprise fee to pay through a link is the sign, however official the shipment number looks.","gently":"The shipment ID is there to look official. The clearest sign is being asked to pay a surprise fee through a link."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('shared-document-sign-in','Shared document sign-in','account_takeover') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 3, 'A document has been shared with you: Family Photos 2026', 'A document has been shared with you.

Family Photos 2026.pdf
(18 pages)

To view this document, sign in with your email address and password:
{link}

This link will expire in 48 hours.

You received this email because someone shared a file with you.', 'Fake shared-document notices collect email passwords.', array['A sign-in page reached from an email link is how passwords are collected. Your email password is the key to all your other accounts.','A real share notice tells you who shared it. ''Someone'' keeps it vague so you''ll assume it''s family.','A tempting, personal-sounding file name is bait.']::text[], 'Whoever has your email password can reset nearly every other password you have, which is why this simple-looking scam is so valuable to criminals. Asking the person who supposedly sent it is the fastest check.', 'draft', '[{"quote":"sign in with your email address and password","note":"A sign-in page reached from an email link is how passwords are collected. Your email password is the key to all your other accounts."},{"quote":"someone shared a file with you","note":"A real share notice tells you who shared it. ''Someone'' keeps it vague so you''ll assume it''s family."},{"quote":"Family Photos 2026.pdf","note":"A tempting, personal-sounding file name is bait."}]'::jsonb, '{"from_name":"Shared Files","from_local":"share-notify"}'::jsonb, 'generic', null, 'human', array['If I''m expecting photos, I''ll ask the person directly whether they sent them.','I won''t type my email password into a page I reached from an email.','If I already did, I''ll change my password and tell someone who can help.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The file is a PDF","It doesn''t say who shared it and asks for your email password","It mentions the year"],"correct":1,"affirm":"Yes. A vague ''someone'' plus a request for your password is the pattern to watch for.","gently":"The details are there to make it feel personal. The sign to notice is that it doesn''t say who shared it, then asks for your password."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-safe-account','Bank fraud team and a "safe account"','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 4, 'Re: Case 55120 - protecting your savings', 'Hello,

Following up on our fraud alert from this morning. We have confirmed that an employee at your local branch may be involved in unauthorized activity on several customer accounts, including yours.

For your protection, we have opened a temporary secure account in your name. Please move your savings into it today so they can''t be accessed. The details are here:
{link}

For your safety, please do not discuss this with branch staff, as the investigation is ongoing.

Fraud Prevention Department', 'Banks never ask you to move money to a ''safe account'' or to keep it from branch staff.', array['Pretending to continue an earlier conversation makes you think you''ve already checked. You haven''t.','A real bank never asks you to move money to keep it safe. Your money is protected where it is.','The branch staff are exactly the people who''d tell you it''s a scam. That''s why they don''t want you talking to them.']::text[], 'The ''safe account'' scam is one of the most expensive there is, because people move their life savings believing they''re protecting them. It''s harder to spot because it borrows the language of fraud protection. Any request to move money to keep it safe is the scam, however it''s explained.', 'draft', '[{"quote":"Following up on our fraud alert from this morning","note":"Pretending to continue an earlier conversation makes you think you''ve already checked. You haven''t."},{"quote":"move your savings into it today","note":"A real bank never asks you to move money to keep it safe. Your money is protected where it is."},{"quote":"please do not discuss this with branch staff","note":"The branch staff are exactly the people who''d tell you it''s a scam. That''s why they don''t want you talking to them."}]'::jsonb, '{"from_name":"Fraud Prevention Department","from_local":"fraud-prevention"}'::jsonb, 'generic', null, 'human', array['I''ll hang up, or close the email, and call the number on the back of my card.','I''ll never move money to a ''safe account'' for anyone.','I''ll tell someone in the family before I move any money.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to move your savings and not tell branch staff","The case number in the subject","Being told about a fraud alert"],"correct":0,"affirm":"Exactly. A request to move money to keep it safe, plus keeping it from the branch, is the scam every time.","gently":"Real banks do send fraud alerts, which is why this one is convincing. The giveaway is being asked to move your savings and keep it from branch staff."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('order-shipped-unknown-address','Order shipped to a strange address','shopping') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 4, 'Your order #114-3920-5581 has shipped', 'Hello,

Good news, your order has shipped.

Item: 65" 4K Smart TV
Order total: $1,149.00
Shipping to: 2290 Lakeview Dr, Apt 4B
Estimated delivery: Friday

Don''t recognize this order or this address? Review your order and report it here:
{link}

Thank you for shopping with us.', 'Fake order confirmations use alarm about a stranger''s purchase to send you to a fake support page.', array['A strange address makes you worry someone is using your account, so you click to fix it.','This is the hook. The ''report'' link leads to a fake sign-in page or a fake support line.','A large purchase you didn''t make is meant to alarm you into acting fast.']::text[], 'This one looks exactly like the order emails people get every week, which is why it''s rated hard. There''s nothing obviously wrong with it. The way to check is the same as always: go to the shop yourself, not through the email.', 'draft', '[{"quote":"Shipping to: 2290 Lakeview Dr, Apt 4B","note":"A strange address makes you worry someone is using your account, so you click to fix it."},{"quote":"Don''t recognize this order or this address?","note":"This is the hook. The ''report'' link leads to a fake sign-in page or a fake support line."},{"quote":"Order total: $1,149.00","note":"A large purchase you didn''t make is meant to alarm you into acting fast."}]'::jsonb, '{"from_name":"Order Updates","from_local":"orders"}'::jsonb, 'generic', null, 'human', array['I''ll open the shop''s app or type its website myself and look at my orders there.','I''ll check my card statement for the charge.','I won''t use links or phone numbers in an order email I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The order number","An order you didn''t place, with a link to ''report'' it","The delivery day"],"correct":1,"affirm":"Yes. An order you didn''t place with a convenient ''report it here'' link is the setup. Checking your account yourself takes care of it.","gently":"The order number looks real, which is what makes this convincing. The sign is an order you didn''t place with a link to report it, which is where the trap is."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('patient-portal-message','New message from your care team','health') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 5, 'You have a new message from your care team', 'You have a new secure message.

A member of your care team has sent you a message about your recent visit, which may include test results.

To read it, sign in to the patient portal:
{link}

For your privacy, the message isn''t included in this email.

Please do not reply to this email. This mailbox is not monitored.', 'Look-alike portal notices collect sign-in details; always open the portal yourself.', array['Test results are something everyone wants to read straight away, and that urge is what this relies on. The email never names your doctor or clinic.','The link leads to a look-alike sign-in page. Open the portal the way you usually do, from a bookmark or the clinic''s website.','Real portals say this too, which is why this one is so hard to spot. The difference is how you get there.']::text[], 'This is the hardest kind, because it''s nearly identical to a real notice. The only things missing are your doctor''s name and the clinic''s name. You don''t have to spot those to stay safe. If you always open the portal yourself, the link never matters.', 'draft', '[{"quote":"about your recent visit, which may include test results","note":"Test results are something everyone wants to read straight away, and that urge is what this relies on. The email never names your doctor or clinic."},{"quote":"sign in to the patient portal","note":"The link leads to a look-alike sign-in page. Open the portal the way you usually do, from a bookmark or the clinic''s website."},{"quote":"For your privacy, the message isn''t included in this email","note":"Real portals say this too, which is why this one is so hard to spot. The difference is how you get there."}]'::jsonb, '{"from_name":"Patient Portal","from_local":"portal-notify"}'::jsonb, 'generic', null, 'human', array['I''ll open the patient portal from my own bookmark or the clinic''s website, never from the email.','If I''m not sure, I''ll call my doctor''s office.','I''ll notice when an email doesn''t name my doctor or clinic.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It doesn''t name your doctor or clinic","It says the mailbox isn''t monitored","It mentions privacy"],"correct":0,"affirm":"Well spotted. Without your doctor''s or clinic''s name, it could be from anyone, and opening the portal yourself sidesteps the whole thing.","gently":"Real portals say those things too, so this one is genuinely hard. The small sign is that it never names your doctor or clinic. Opening the portal yourself sidesteps the question."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('phantom-hacker-federal','Hacker warning and a federal agent','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'email', 5, 'Security incident on your accounts: reference SP-40418', 'Hello,

We''re writing because our monitoring detected that your computer was accessed by an overseas group, and they may now be able to see your bank and retirement accounts.

This incident has been referred to a federal agency. An agent will contact you by phone today to help secure your funds. Please follow their instructions carefully and keep this matter confidential, including from family members, as it is part of an active investigation.

You can confirm your incident details here:
{link}

Customer Protection Services
Incident Response', 'The ''phantom hacker'' scam chains a tech scare, a fake bank, and a fake government agent to move savings.', array['Government agencies never call to help move your money. This sets up the next step of the scam, a phone call from someone posing as an official.','Secrecy from family is the biggest warning sign of all. A real investigation never asks it.','A frightening, hard-to-check claim is how this scam begins. You can''t see it, so you have to take their word for it.']::text[], 'This is a version of what the FBI calls the phantom hacker scam, which has cost older Americans enormous sums. It plays out in stages: a scare, then a fake bank or tech contact, then a fake government agent who tells you to move money. Each step makes the next one feel more believable. Telling family is what breaks the chain.', 'draft', '[{"quote":"An agent will contact you by phone today to help secure your funds","note":"Government agencies never call to help move your money. This sets up the next step of the scam, a phone call from someone posing as an official."},{"quote":"keep this matter confidential, including from family members","note":"Secrecy from family is the biggest warning sign of all. A real investigation never asks it."},{"quote":"your computer was accessed by an overseas group","note":"A frightening, hard-to-check claim is how this scam begins. You can''t see it, so you have to take their word for it."}]'::jsonb, '{"from_name":"Customer Protection Services","from_local":"protection"}'::jsonb, 'generic', null, 'human', array['I''ll tell someone in the family straight away, whatever I''ve been asked.','I won''t move money because of a call or email, even from someone who says they''re from the government.','I''ll call my bank on the number on my card.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to keep it secret from family and wait for an agent to help with your money","The reference number","It being sent by an incident response team"],"correct":0,"affirm":"Yes. Secrecy from family and an ''agent'' who''ll help with your money are the two parts that give it away.","gently":"The official-sounding details are there to make you trust it. The clearest signs are the secrecy from family and the promise of an agent to help with your money."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='email');
with scam as (insert into public.practice_scams(stable_code,name,category) values('delivery-redelivery-fee','Parcel redelivery fee','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 1, null, 'Hello. This is an automated message from the parcel delivery service. We tried to deliver your package today, but there is an unpaid redelivery fee of one dollar and ninety-nine cents.

To pay the fee now and schedule your delivery, press 1 or say yes.

If the fee is not paid today, your package will be returned to the sender. Press 1 now to keep your delivery.', 'Delivery companies don''t call to collect fees.', array['Delivery companies don''t phone you to collect a fee for trying again.','No company name and no tracking number, so it could be about anyone''s parcel.','The deadline is there to hurry you.']::text[], 'Recorded delivery calls work for the same reason the texts do: most people have something on the way. The small fee is the door to your card number.', 'draft', '[{"quote":"an unpaid redelivery fee","note":"Delivery companies don''t phone you to collect a fee for trying again."},{"quote":"This is an automated message from the parcel delivery service","note":"No company name and no tracking number, so it could be about anyone''s parcel."},{"quote":"If the fee is not paid today","note":"The deadline is there to hurry you."}]'::jsonb, '{"script":{"opening":"Hello. This is an automated message from the parcel delivery service. We tried to deliver your package today, but there is an unpaid redelivery fee of one dollar and ninety-nine cents.","hook":"To pay the fee now and schedule your delivery, press 1 or say yes.","pressure":"If the fee is not paid today, your package will be returned to the sender. Press 1 now to keep your delivery."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and check the tracking on the shop''s own website.','I won''t give a card number to a recorded call.','If I''m not expecting a parcel, I''ll ignore it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A recorded call asking you to pay a redelivery fee","The call coming in the daytime","The mention of a parcel"],"correct":0,"affirm":"That''s right. A delivery company won''t call asking for a fee.","gently":"Understandable, but the clearest sign is the fee itself. A delivery company won''t call to collect one."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('prize-processing-fee','Sweepstakes win with a fee','prize') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 1, null, 'Congratulations! This is the Prize Notification Center. Your phone number was selected as a grand prize winner of eight hundred and fifty thousand dollars.

To claim your prize, press 1 or say yes, and an agent will explain the small processing fee.

This offer expires at the end of today. Please do not tell anyone until your winnings are released. Press 1 now.', 'Paying a fee to collect a prize is the prize scam.', array['You can''t win a contest you never entered.','Paying to receive a prize is the scam, every time it comes up.','Secrecy keeps you from talking to someone who''d spot it at once.']::text[], 'Prize calls are built on hope. Whatever the amount, they come down to one request: send a little money to receive a lot.', 'draft', '[{"quote":"Your phone number was selected","note":"You can''t win a contest you never entered."},{"quote":"the small processing fee","note":"Paying to receive a prize is the scam, every time it comes up."},{"quote":"Please do not tell anyone","note":"Secrecy keeps you from talking to someone who''d spot it at once."}]'::jsonb, '{"script":{"opening":"Congratulations! This is the Prize Notification Center. Your phone number was selected as a grand prize winner of eight hundred and fifty thousand dollars.","hook":"To claim your prize, press 1 or say yes, and an agent will explain the small processing fee.","pressure":"This offer expires at the end of today. Please do not tell anyone until your winnings are released. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['If I didn''t enter, I didn''t win, so I''ll hang up.','I won''t pay anything to collect a prize.','I''ll tell someone in the family about calls like this.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Winning something you never entered, with a fee to collect","The size of the prize","The cheerful voice"],"correct":0,"affirm":"Yes. A contest you didn''t enter and a fee to collect give it away.","gently":"The big number is eye-catching, but the clearest sign is winning something you never entered and paying to collect it."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('tech-support-virus-alert','Virus warning call','tech_support') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 1, null, 'This is the Computer Security Center calling about your computer. Our system has detected five viruses, and your personal files and banking information may be at risk.

To speak with a certified technician who can remove them now, press 1 or say yes.

Please do not turn off your computer, as this may cause permanent data loss. A technician is standing by. Press 1.', 'Unsolicited calls about viruses are tech support scams.', array['Nobody can see viruses on your computer from the outside and call you about them.','Turning it off is safe. This line keeps you anxious and on the phone.','The ''technician'' asks to connect to your computer, then for payment or your bank login.']::text[], 'Tech support scams start with a scare and end with someone connected to your computer. Real companies don''t call you about viruses.', 'draft', '[{"quote":"Our system has detected five viruses","note":"Nobody can see viruses on your computer from the outside and call you about them."},{"quote":"Please do not turn off your computer","note":"Turning it off is safe. This line keeps you anxious and on the phone."},{"quote":"a certified technician","note":"The ''technician'' asks to connect to your computer, then for payment or your bank login."}]'::jsonb, '{"script":{"opening":"This is the Computer Security Center calling about your computer. Our system has detected five viruses, and your personal files and banking information may be at risk.","hook":"To speak with a certified technician who can remove them now, press 1 or say yes.","pressure":"Please do not turn off your computer, as this may cause permanent data loss. A technician is standing by. Press 1."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up on anyone who calls about my computer out of the blue.','If I''m worried, I''ll ask someone I know or a shop I choose.','I won''t let a caller connect to my computer.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller claiming they can see viruses on your computer","The word ''certified''","Being asked to keep the computer on"],"correct":0,"affirm":"That''s it. Nobody can see your computer from the outside.","gently":"That line is designed to scare you. The first sign is the claim itself: nobody can see your computer from outside."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-account-locked','Bank account locked','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 1, null, 'This is the account security team at your bank. We noticed unusual sign-in activity and have locked your account for your protection.

To unlock it now, press 1 or say yes, and have your card number and PIN ready.

If you do not verify within the next hour, your account will be closed. Press 1 to verify now.', 'Your bank never asks for your PIN on the phone.', array['It never says which bank. Your real bank would.','No bank ever asks for your PIN.','Banks don''t close accounts because you didn''t answer a call.']::text[], 'Account-locked calls make your money feel in danger and offer a quick fix. Hanging up and calling the number on your card tells you the truth in a minute.', 'draft', '[{"quote":"the account security team at your bank","note":"It never says which bank. Your real bank would."},{"quote":"your card number and PIN","note":"No bank ever asks for your PIN."},{"quote":"your account will be closed","note":"Banks don''t close accounts because you didn''t answer a call."}]'::jsonb, '{"script":{"opening":"This is the account security team at your bank. We noticed unusual sign-in activity and have locked your account for your protection.","hook":"To unlock it now, press 1 or say yes, and have your card number and PIN ready.","pressure":"If you do not verify within the next hour, your account will be closed. Press 1 to verify now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call the number on the back of my card.','I''ll never give my PIN to anyone who calls.','I''ll check my account the way I always do.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked for your card number and PIN","Hearing about unusual activity","A call from a security team"],"correct":0,"affirm":"Yes. A bank will never ask for your PIN.","gently":"Banks do mention unusual activity, which is why this works. The giveaway is the request for your PIN."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('utility-shutoff-today','Power shut-off today','utility') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 2, null, 'This is the utility billing department with a final disconnection notice. Your electric service is scheduled to be shut off today at four o''clock for a past-due balance.

To avoid disconnection, press 1 or say yes to pay now by prepaid gift card.

Do not contact your local office, as they cannot stop the disconnection. Only this line can help. Press 1 now.', 'Same-day shut-off threats and gift cards are utility scam signs.', array['Utilities send written notices for weeks before any shut-off.','No utility takes gift cards.','Being told not to check is the clearest sign of all.']::text[], 'Utility scams use the fear of losing power. A real utility gives written notice and takes ordinary payments, and is happy for you to call them.', 'draft', '[{"quote":"scheduled to be shut off today at four o''clock","note":"Utilities send written notices for weeks before any shut-off."},{"quote":"prepaid gift card","note":"No utility takes gift cards."},{"quote":"Do not contact your local office","note":"Being told not to check is the clearest sign of all."}]'::jsonb, '{"script":{"opening":"This is the utility billing department with a final disconnection notice. Your electric service is scheduled to be shut off today at four o''clock for a past-due balance.","hook":"To avoid disconnection, press 1 or say yes to pay now by prepaid gift card.","pressure":"Do not contact your local office, as they cannot stop the disconnection. Only this line can help. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call the number on my last paper bill.','I''ll never pay a bill with a gift card.','I''ll ask someone if I''m unsure.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being told not to contact your local office","The four o''clock time","The word ''final''"],"correct":0,"affirm":"Right. A real company never tells you not to check with them.","gently":"The time is meant to rush you. The surest sign is being told not to contact your local office."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('jury-duty-warrant','Missed jury duty','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 2, null, 'This is the county court jury division. Our records show you did not report for jury duty, and a warrant may be issued for your arrest.

To resolve this today by paying the fine, press 1 or say yes to speak with an officer.

If you do not respond, officers may be sent to your address. Press 1 now to avoid further action.', 'Courts don''t threaten arrest or collect fines by phone.', array['Courts don''t threaten arrest on the phone.','Paying a caller never cancels a warrant, and courts don''t take payment this way.','The threat is there to frighten you into paying.']::text[], 'Jury duty scams rely on worry and embarrassment. A quick call to the court clerk, on a number you found, puts it to rest.', 'draft', '[{"quote":"a warrant may be issued for your arrest","note":"Courts don''t threaten arrest on the phone."},{"quote":"by paying the fine","note":"Paying a caller never cancels a warrant, and courts don''t take payment this way."},{"quote":"officers may be sent to your address","note":"The threat is there to frighten you into paying."}]'::jsonb, '{"script":{"opening":"This is the county court jury division. Our records show you did not report for jury duty, and a warrant may be issued for your arrest.","hook":"To resolve this today by paying the fine, press 1 or say yes to speak with an officer.","pressure":"If you do not respond, officers may be sent to your address. Press 1 now to avoid further action."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call the court clerk on a number I look up.','I won''t pay a fine over the phone to someone who called me.','I''ll tell family, since these count on embarrassment.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller offering to cancel a warrant if you pay a fine","The word ''county''","An automated voice"],"correct":0,"affirm":"Yes. Courts don''t take a payment over the phone to cancel a warrant.","gently":"Official words are part of the disguise. The sign is the offer to make a warrant go away if you pay."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('family-new-email','"It''s me" on the phone','family_emergency') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 2, null, 'Hi, it''s me. Please don''t be upset. I''m in some trouble and I lost my phone, so I''m calling from a friend''s. I really need help paying something today.

Can you help me? Press 1 or say yes and my friend will tell you where to send the money.

Please don''t tell Mom or Dad yet, I''ll explain everything later. I really need you right now. Press 1.', '"It''s me" calls asking for urgent, secret money are family emergency scams.', array['Someone you know would say their name. ''It''s me'' lets you fill in who you think it is.','This stops you from calling them back on their own number, which is exactly what to do.','Secrecy keeps you from finding out they''re fine.']::text[], 'This is the grandparent scam, and voices can now be faked with AI, so the voice itself is not proof. Calling the number you already have settles it.', 'draft', '[{"quote":"Hi, it''s me","note":"Someone you know would say their name. ''It''s me'' lets you fill in who you think it is."},{"quote":"I lost my phone, so I''m calling from a friend''s","note":"This stops you from calling them back on their own number, which is exactly what to do."},{"quote":"Please don''t tell Mom or Dad yet","note":"Secrecy keeps you from finding out they''re fine."}]'::jsonb, '{"script":{"opening":"Hi, it''s me. Please don''t be upset. I''m in some trouble and I lost my phone, so I''m calling from a friend''s. I really need help paying something today.","hook":"Can you help me? Press 1 or say yes and my friend will tell you where to send the money.","pressure":"Please don''t tell Mom or Dad yet, I''ll explain everything later. I really need you right now. Press 1."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call them on the number I already have.','If I can''t reach them, I''ll call someone else in the family.','We''ll agree a family code word for emergencies.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["No name, a borrowed phone, and a request to keep it secret","The caller sounding upset","The call coming in the day"],"correct":0,"affirm":"Exactly. Those three together are how these keep you from checking.","gently":"Sounding upset is part of the act. The clearest sign is no name, a borrowed phone and the secrecy."}'::jsonb, '/scam-alerts/ai-voice-cloning-grandparent-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('charity-disaster-match','Disaster relief appeal','charity') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 2, null, 'Hello, I''m calling for the Storm Relief Fund. Thousands of families lost their homes this week, and tonight every gift is doubled by a generous donor, but only until midnight.

Can we count on you for fifty dollars tonight? Press 1 or say yes.

Gifts by gift card or wire transfer reach families fastest. The match ends at midnight. Press 1 to give now.', 'Fake charities use deadlines and untraceable payments.', array['Real charities welcome gifts any time. A countdown stops you looking them up.','Established charities don''t ask for gift cards or wires.','A name that sounds right but you''ve never heard of is worth looking up first.']::text[], 'Fake charity calls appear after every disaster. Giving through a charity you know, on its own website, gets your money to the right place.', 'draft', '[{"quote":"only until midnight","note":"Real charities welcome gifts any time. A countdown stops you looking them up."},{"quote":"Gifts by gift card or wire transfer","note":"Established charities don''t ask for gift cards or wires."},{"quote":"Storm Relief Fund","note":"A name that sounds right but you''ve never heard of is worth looking up first."}]'::jsonb, '{"script":{"opening":"Hello, I''m calling for the Storm Relief Fund. Thousands of families lost their homes this week, and tonight every gift is doubled by a generous donor, but only until midnight.","hook":"Can we count on you for fifty dollars tonight? Press 1 or say yes.","pressure":"Gifts by gift card or wire transfer reach families fastest. The match ends at midnight. Press 1 to give now."}}'::jsonb, 'generic', null, 'human', array['I''ll give to charities I already know, on their own websites.','I won''t give over the phone to a charity that called me.','I won''t give by gift card or wire.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Asking for a gift card or wire transfer","Mentioning storms","Asking for fifty dollars"],"correct":0,"affirm":"Yes. Real charities don''t ask for gift cards or wires.","gently":"Real news makes it convincing. The clearest sign is the payment method."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('medicare-plan-change','Medicare plan ending','medicare') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'Hello, this is the Medicare benefits office calling during Open Enrollment. Your current plan has been flagged for changes that could leave you without coverage on January first.

To review your coverage now with a benefits advisor, press 1 or say yes. Please have your Medicare number ready.

Advisors are only available for the next forty-eight hours. Press 1 now to avoid a gap in coverage.', 'Medicare doesn''t call asking for your Medicare number.', array['Medicare doesn''t call to ask for your number. It''s used to bill for things you never got.','Open Enrollment lasts for weeks. Nobody official gives you 48 hours.','Medicare doesn''t make calls like this. If something needed checking, you''d get a letter.']::text[], 'This one arrives during real Open Enrollment, when you''re expecting news about your plan, which makes it harder. The short deadline and the request for your number give it away.', 'draft', '[{"quote":"Please have your Medicare number ready","note":"Medicare doesn''t call to ask for your number. It''s used to bill for things you never got."},{"quote":"for the next forty-eight hours","note":"Open Enrollment lasts for weeks. Nobody official gives you 48 hours."},{"quote":"this is the Medicare benefits office calling","note":"Medicare doesn''t make calls like this. If something needed checking, you''d get a letter."}]'::jsonb, '{"script":{"opening":"Hello, this is the Medicare benefits office calling during Open Enrollment. Your current plan has been flagged for changes that could leave you without coverage on January first.","hook":"To review your coverage now with a benefits advisor, press 1 or say yes. Please have your Medicare number ready.","pressure":"Advisors are only available for the next forty-eight hours. Press 1 now to avoid a gap in coverage."}}'::jsonb, 'generic', '2026-12-08'::timestamptz, 'human', array['I''ll hang up and call the number on my Medicare card.','I won''t give my Medicare number to anyone who calls me.','I''ll review plans with someone I trust, like a SHIP counselor.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller asking for your Medicare number with a 48-hour deadline","Mentioning Open Enrollment","Mentioning January first"],"correct":0,"affirm":"That''s right. That combination is the one to watch for.","gently":"The timing makes it believable. The giveaway is the deadline and the request for your number."}'::jsonb, '/scam-alerts/medicare-open-enrollment-scams'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('tax-refund-pending','Tax refund waiting','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'This is the tax refund department. After a review of your recent filing, you are eligible for an additional refund of twelve hundred and eighty-four dollars.

To receive it by direct deposit, press 1 or say yes, and an agent will confirm your bank details and Social Security number.

Refunds not claimed within five business days are returned to the Treasury. Press 1 now.', 'The tax agency doesn''t call about refunds or ask for your Social Security number.', array['The tax agency contacts people by post, not by phone, about refunds.','Those two together let someone take over your accounts.','A refund you''re owed doesn''t vanish because you didn''t answer quickly.']::text[], 'Good news lowers people''s guard, which is why refund calls work. The request for your bank and Social Security details is what to notice.', 'draft', '[{"quote":"you are eligible for an additional refund","note":"The tax agency contacts people by post, not by phone, about refunds."},{"quote":"your bank details and Social Security number","note":"Those two together let someone take over your accounts."},{"quote":"within five business days","note":"A refund you''re owed doesn''t vanish because you didn''t answer quickly."}]'::jsonb, '{"script":{"opening":"This is the tax refund department. After a review of your recent filing, you are eligible for an additional refund of twelve hundred and eighty-four dollars.","hook":"To receive it by direct deposit, press 1 or say yes, and an agent will confirm your bank details and Social Security number.","pressure":"Refunds not claimed within five business days are returned to the Treasury. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and check on the tax agency''s website, typing the address myself.','I''ll never give my Social Security number to someone who called me.','I''ll ask someone I trust if I''m unsure.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked for bank details and your Social Security number on a call","The refund amount","The word ''Treasury''"],"correct":0,"affirm":"Yes. Nobody official asks for those on a call they made.","gently":"The exact amount is there to seem real. The clearest sign is the request for your bank and Social Security details."}'::jsonb, null
