with scam as (insert into public.practice_scams(stable_code,name,category) values('subscription-renewal-refund','Surprise renewal charge','tech_support') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'Hello, this is billing support. Your annual device protection plan renewed today for three hundred ninety-nine dollars and ninety-nine cents.

If you did not authorize this charge and want a refund, press 1 or say yes to speak with a refund agent.

Refund requests must be made within twenty-four hours. After that, the charge cannot be reversed. Press 1 now.', 'Fake renewal calls push you to ''cancel'' through a scammer.', array['If you don''t recognize the plan, there isn''t one. The surprise is what pulls you in.','The ''refund'' ends with someone on your computer or in your bank account.','The rush stops you checking your real statement.']::text[], 'Fake renewal calls make you want to protect yourself, and that urge is the trap. Your own statement will tell you if anything was charged.', 'draft', '[{"quote":"Your annual device protection plan","note":"If you don''t recognize the plan, there isn''t one. The surprise is what pulls you in."},{"quote":"to speak with a refund agent","note":"The ''refund'' ends with someone on your computer or in your bank account."},{"quote":"within twenty-four hours","note":"The rush stops you checking your real statement."}]'::jsonb, '{"script":{"opening":"Hello, this is billing support. Your annual device protection plan renewed today for three hundred ninety-nine dollars and ninety-nine cents.","hook":"If you did not authorize this charge and want a refund, press 1 or say yes to speak with a refund agent.","pressure":"Refund requests must be made within twenty-four hours. After that, the charge cannot be reversed. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and check my card statement myself.','If there''s a charge I don''t know, I''ll call the number on my card.','I won''t let a refund caller connect to my computer.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A charge for something you never bought, with 24 hours to act","The price ending in 99 cents","The word ''billing''"],"correct":0,"affirm":"Right. A charge you don''t recognize and a short window is the setup.","gently":"Prices like that are normal. The sign is a charge for something you never bought and the rush to act."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('romance-wrong-address','Friendly stranger calling','romance') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'Oh, hello. I''m so sorry, I think I''ve dialled the wrong number. I was trying to reach an old friend from my years in the service. You have such a kind voice, though.

It''s been a lonely year since I lost my wife, and I''m working overseas right now. Would you mind if I called again sometime? Press 1 or say yes.

I''d really like to stay in touch. I have some photos from where I''m working that I''d love to send you. Press 1.', '"Wrong number" openers from lonely, overseas strangers are how romance scams begin.', array['The wrong-number opener is a way to start talking to a stranger without seeming like a pitch.','Sharing a loss straight away builds sympathy fast.','Working abroad explains why they can never meet, and later why they need money.']::text[], 'Romance scams start slowly and kindly. The opening is the easiest place to spot them, because it follows a familiar pattern.', 'draft', '[{"quote":"I think I''ve dialled the wrong number","note":"The wrong-number opener is a way to start talking to a stranger without seeming like a pitch."},{"quote":"It''s been a lonely year since I lost my wife","note":"Sharing a loss straight away builds sympathy fast."},{"quote":"I''m working overseas","note":"Working abroad explains why they can never meet, and later why they need money."}]'::jsonb, '{"script":{"opening":"Oh, hello. I''m so sorry, I think I''ve dialled the wrong number. I was trying to reach an old friend from my years in the service. You have such a kind voice, though.","hook":"It''s been a lonely year since I lost my wife, and I''m working overseas right now. Would you mind if I called again sometime? Press 1 or say yes.","pressure":"I''d really like to stay in touch. I have some photos from where I''m working that I''d love to send you. Press 1."}}'::jsonb, 'generic', null, 'human', array['I''ll end calls from strangers who rang ''by mistake''.','I won''t share my details with someone I don''t know.','I''ll never send money to someone I haven''t met in person.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A stranger calling by mistake, sharing a loss, and working overseas","His politeness","Mentioning the service"],"correct":0,"affirm":"Yes. That pattern is how these usually begin.","gently":"Politeness is part of the charm. The pattern to notice is the wrong number, the shared loss and the job overseas."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('voter-registration-problem','Voter registration problem','election') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'This is the election records office calling about your voter registration. During a routine review, we found a problem that may prevent you from voting this year.

To fix it now, press 1 or say yes, and be ready to confirm your date of birth and the last four digits of your Social Security number.

Registrations that are not confirmed may be removed from the voter rolls. Press 1 now to keep your vote.', 'Election offices don''t call asking for your Social Security number.', array['Election offices write to you about problems, and you can check online yourself.','Nobody needs that on a call to keep you registered.','The threat of losing your vote is meant to rush you.']::text[], 'Election scams rise before a vote. Checking your own registration takes a couple of minutes.', 'draft', '[{"quote":"we found a problem that may prevent you from voting","note":"Election offices write to you about problems, and you can check online yourself."},{"quote":"the last four digits of your Social Security number","note":"Nobody needs that on a call to keep you registered."},{"quote":"may be removed from the voter rolls","note":"The threat of losing your vote is meant to rush you."}]'::jsonb, '{"script":{"opening":"This is the election records office calling about your voter registration. During a routine review, we found a problem that may prevent you from voting this year.","hook":"To fix it now, press 1 or say yes, and be ready to confirm your date of birth and the last four digits of your Social Security number.","pressure":"Registrations that are not confirmed may be removed from the voter rolls. Press 1 now to keep your vote."}}'::jsonb, 'generic', '2026-11-04'::timestamptz, 'human', array['I''ll check my registration on my state''s official election website.','I''ll call my county election office if I''m unsure.','I won''t give personal details to someone who called me.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller asking for part of your Social Security number","Mentioning the election","A routine review"],"correct":0,"affirm":"Right. No election office asks for that on a call.","gently":"The timing makes it feel real. The clearest sign is the request for your Social Security number."}'::jsonb, '/scam-alerts/weekly-2026-10-19'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('benefits-suspended','Benefits suspended','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'This is the benefits administration. Your monthly benefits have been suspended due to suspicious activity linked to your Social Security number. Case number B A 2 2 0 7.

To speak with your assigned case officer and reinstate your benefits, press 1 or say yes.

If you do not respond today, the hold on your benefits may become permanent. Press 1 now.', 'Benefits aren''t suspended by phone.', array['A Social Security number can''t be suspended, and benefits aren''t stopped by phone.','The ''case officer'' is the scammer.','A case number makes it sound official. Anyone can make one up.']::text[], 'Government impersonation takes a real worry and dresses it up with official details. A call to the agency on a number you found clears it up.', 'draft', '[{"quote":"suspicious activity linked to your Social Security number","note":"A Social Security number can''t be suspended, and benefits aren''t stopped by phone."},{"quote":"your assigned case officer","note":"The ''case officer'' is the scammer."},{"quote":"Case number B A 2 2 0 7","note":"A case number makes it sound official. Anyone can make one up."}]'::jsonb, '{"script":{"opening":"This is the benefits administration. Your monthly benefits have been suspended due to suspicious activity linked to your Social Security number. Case number B A 2 2 0 7.","hook":"To speak with your assigned case officer and reinstate your benefits, press 1 or say yes.","pressure":"If you do not respond today, the hold on your benefits may become permanent. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call the agency on a number I look up myself.','I''ll check my benefits by signing in the usual way.','I won''t speak to a ''case officer'' who called me.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller saying your benefits are suspended over your Social Security number","The case number","An automated voice"],"correct":0,"affirm":"Yes. Benefits aren''t suspended by phone.","gently":"The case number is there to sound official. The giveaway is the claim itself."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('customs-duty-package','Customs fee on a package','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'This is international shipping customs. A package addressed to you is being held pending payment of import duty of twelve dollars and sixty cents.

To pay the duty now and release your package, press 1 or say yes.

After three days the package will be returned and a storage fee will apply. Press 1 to pay now.', 'Surprise customs fees by phone are a variation on the delivery fee scam.', array['Shops and carriers tell you about duties at checkout or on delivery, not by phone.','A small, exact amount feels routine. The aim is your card number.','Adding a penalty is another way to hurry you.']::text[], 'This is a cousin of the redelivery fee scam. Most people don''t know how customs fees work, which is what makes it believable.', 'draft', '[{"quote":"being held pending payment of import duty","note":"Shops and carriers tell you about duties at checkout or on delivery, not by phone."},{"quote":"twelve dollars and sixty cents","note":"A small, exact amount feels routine. The aim is your card number."},{"quote":"a storage fee will apply","note":"Adding a penalty is another way to hurry you."}]'::jsonb, '{"script":{"opening":"This is international shipping customs. A package addressed to you is being held pending payment of import duty of twelve dollars and sixty cents.","hook":"To pay the duty now and release your package, press 1 or say yes.","pressure":"After three days the package will be returned and a storage fee will apply. Press 1 to pay now."}}'::jsonb, 'generic', null, 'human', array['I''ll check the order on the shop''s own website.','I won''t pay a customs fee to a caller.','I''ll hang up.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A surprise call asking for a customs fee","The amount","Three days to pay"],"correct":0,"affirm":"Right. A surprise fee on a call is the sign.","gently":"The amount is meant to feel routine. The sign is the surprise fee on a call."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('shared-document-sign-in','Email account warning','account_takeover') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 3, null, 'This is the email security team. Someone has tried to sign in to your email account from another country, and your messages and photos may be exposed.

To secure your account now, press 1 or say yes, and an agent will help you reset your password.

If we don''t hear from you, your account will be suspended within the hour. Press 1 now.', 'Calls offering to help you reset a password are account takeover scams.', array['Email providers don''t phone you about sign-ins.','Anyone who helps you reset a password on a call they made ends up with it.','The deadline is there to stop you checking.']::text[], 'Whoever has your email password can reset nearly every other password. That''s why these calls are worth so much to scammers.', 'draft', '[{"quote":"the email security team","note":"Email providers don''t phone you about sign-ins."},{"quote":"help you reset your password","note":"Anyone who helps you reset a password on a call they made ends up with it."},{"quote":"suspended within the hour","note":"The deadline is there to stop you checking."}]'::jsonb, '{"script":{"opening":"This is the email security team. Someone has tried to sign in to your email account from another country, and your messages and photos may be exposed.","hook":"To secure your account now, press 1 or say yes, and an agent will help you reset your password.","pressure":"If we don''t hear from you, your account will be suspended within the hour. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and check my email account myself.','I''ll never tell a caller my password or a code sent to me.','I''ll ask someone to help me change my password if I''m worried.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller offering to help you reset your password","Mentioning another country","The word ''security''"],"correct":0,"affirm":"Yes. Nobody should help you with a password on a call they made.","gently":"The scary details are there to rush you. The sign is the offer to help with your password."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-safe-account','Bank fraud team and a "safe account"','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 4, null, 'Hello, this is the fraud prevention department following up on this morning''s alert. We''ve confirmed that an employee at your local branch may be involved in unauthorized activity on your account.

For your protection, we''ve opened a secure account in your name. Press 1 or say yes, and we''ll help you move your savings into it today.

Please don''t discuss this with branch staff while the investigation is ongoing. Every hour your money stays where it is, it''s at risk. Press 1.', 'Banks never ask you to move money to a ''safe account'' or keep it from branch staff.', array['Pretending to continue an earlier call makes you think you''ve already checked.','A real bank never asks you to move money to keep it safe.','Branch staff would tell you it''s a scam, which is why they want you away from them.']::text[], 'The ''safe account'' scam is one of the costliest, because people move their savings believing they''re protecting them. Any request to move money to keep it safe is the scam.', 'draft', '[{"quote":"following up on this morning''s alert","note":"Pretending to continue an earlier call makes you think you''ve already checked."},{"quote":"we''ll help you move your savings into it today","note":"A real bank never asks you to move money to keep it safe."},{"quote":"Please don''t discuss this with branch staff","note":"Branch staff would tell you it''s a scam, which is why they want you away from them."}]'::jsonb, '{"script":{"opening":"Hello, this is the fraud prevention department following up on this morning''s alert. We''ve confirmed that an employee at your local branch may be involved in unauthorized activity on your account.","hook":"For your protection, we''ve opened a secure account in your name. Press 1 or say yes, and we''ll help you move your savings into it today.","pressure":"Please don''t discuss this with branch staff while the investigation is ongoing. Every hour your money stays where it is, it''s at risk. Press 1."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call the number on the back of my card.','I''ll never move money to a ''safe account'' for anyone.','I''ll tell someone in the family before I move any money.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to move your savings and keep it from branch staff","Hearing about a fraud alert","A calm, professional voice"],"correct":0,"affirm":"Exactly. That''s the scam however it''s explained.","gently":"Banks do call about fraud, which is why this works. The giveaway is moving your savings and keeping it from the branch."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('order-shipped-unknown-address','Order you didn''t place','shopping') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 4, null, 'Hello, this is order support with a fraud check. An order for a sixty-five inch smart TV, eleven hundred and forty-nine dollars, is about to ship to an address we don''t have on file for you.

If you did not place this order, press 1 or say yes to cancel it with an agent.

The order ships within the hour, and after that we can''t stop the charge. Press 1 now.', 'Fake order alerts use alarm about a stranger''s purchase to reach a fake agent.', array['A strange address makes you worry someone is in your account, so you act fast.','The ''agent'' is the scammer, and cancelling leads to a request for your login or card.','The deadline stops you checking your account yourself.']::text[], 'This sounds like a helpful fraud check, which is why it''s rated hard. The check is always the same: look at your account yourself.', 'draft', '[{"quote":"an address we don''t have on file for you","note":"A strange address makes you worry someone is in your account, so you act fast."},{"quote":"to cancel it with an agent","note":"The ''agent'' is the scammer, and cancelling leads to a request for your login or card."},{"quote":"after that we can''t stop the charge","note":"The deadline stops you checking your account yourself."}]'::jsonb, '{"script":{"opening":"Hello, this is order support with a fraud check. An order for a sixty-five inch smart TV, eleven hundred and forty-nine dollars, is about to ship to an address we don''t have on file for you.","hook":"If you did not place this order, press 1 or say yes to cancel it with an agent.","pressure":"The order ships within the hour, and after that we can''t stop the charge. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and look at my orders in the shop''s app or website.','I''ll check my card statement for the charge.','I won''t give a caller my login or card details.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A caller offering to cancel an order you didn''t place","The price of the TV","The word ''fraud''"],"correct":0,"affirm":"Yes. The helpful ''cancel it with an agent'' is the setup.","gently":"It sounds helpful, which is the point. The sign is a caller offering to cancel an order you never placed."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('patient-portal-message','Call about test results','health') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 5, null, 'Hello, this is the patient services line calling about your recent visit. There is a new message from your care team, which may include test results.

To verify your identity and hear the message now, press 1 or say yes. You''ll need your date of birth and insurance member number.

For your privacy, we can only hold the message for today. Press 1 to continue.', 'Calls about results that don''t name your clinic are worth checking by calling back.', array['It never names your doctor or clinic.','Your insurance number is valuable for billing fraud. Your doctor''s office would know who you are.','Real results don''t disappear at the end of the day.']::text[], 'This is the hardest kind, because medical offices really do call. If you always call your doctor back on the number you know, it doesn''t matter who called.', 'draft', '[{"quote":"the patient services line","note":"It never names your doctor or clinic."},{"quote":"your date of birth and insurance member number","note":"Your insurance number is valuable for billing fraud. Your doctor''s office would know who you are."},{"quote":"we can only hold the message for today","note":"Real results don''t disappear at the end of the day."}]'::jsonb, '{"script":{"opening":"Hello, this is the patient services line calling about your recent visit. There is a new message from your care team, which may include test results.","hook":"To verify your identity and hear the message now, press 1 or say yes. You''ll need your date of birth and insurance member number.","pressure":"For your privacy, we can only hold the message for today. Press 1 to continue."}}'::jsonb, 'generic', null, 'human', array['I''ll hang up and call my doctor''s office on the number I have.','I''ll check results in the patient portal the way I usually do.','I''ll notice when a caller doesn''t name my doctor or clinic.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It never names your doctor or clinic","It mentions test results","It''s an automated call"],"correct":0,"affirm":"Well spotted. Without a name, it could be anyone.","gently":"Real offices mention results too, so this one is hard. The small sign is that it never names your doctor or clinic."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('phantom-hacker-federal','Hacker warning and a federal agent','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'phone', 5, null, 'This is customer protection services. Our monitoring detected that your computer was accessed by an overseas group, and they may be able to see your bank and retirement accounts.

This has been referred to a federal agency. To be connected with an agent who will help secure your funds today, press 1 or say yes.

For your safety, keep this confidential, including from family members. It is part of an active investigation. Press 1 now.', 'The ''phantom hacker'' scam chains a tech scare, a fake bank and a fake agent.', array['Government agencies never call to help move your money.','Secrecy from family is the biggest warning sign of all.','A frightening claim you can''t check is how this scam starts.']::text[], 'This is a version of what the FBI calls the phantom hacker scam. Each step makes the next one more believable. Telling family breaks the chain.', 'draft', '[{"quote":"an agent who will help secure your funds","note":"Government agencies never call to help move your money."},{"quote":"keep this confidential, including from family members","note":"Secrecy from family is the biggest warning sign of all."},{"quote":"your computer was accessed by an overseas group","note":"A frightening claim you can''t check is how this scam starts."}]'::jsonb, '{"script":{"opening":"This is customer protection services. Our monitoring detected that your computer was accessed by an overseas group, and they may be able to see your bank and retirement accounts.","hook":"This has been referred to a federal agency. To be connected with an agent who will help secure your funds today, press 1 or say yes.","pressure":"For your safety, keep this confidential, including from family members. It is part of an active investigation. Press 1 now."}}'::jsonb, 'generic', null, 'human', array['I''ll tell someone in the family straight away, whatever I''ve been asked.','I won''t move money because of a call, even from someone who says they''re from the government.','I''ll call my bank on the number on my card.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being told to keep it from family and let an agent secure your money","The word ''overseas''","An official-sounding department"],"correct":0,"affirm":"Yes. Secrecy from family and an agent for your money give it away.","gently":"The scary details rush you. The clearest signs are the secrecy and the agent for your money."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='phone');
with scam as (insert into public.practice_scams(stable_code,name,category) values('delivery-redelivery-fee','Parcel redelivery fee','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 1, null, 'Parcel Notice: we couldn''t deliver your package today. A $1.99 redelivery fee is due within 24 hrs or it returns to sender. Pay here: {link}', 'Fees by text for redelivery are a common way to collect card numbers.', array['Delivery companies don''t text you asking for a fee. The small amount is there to get your card number.','The deadline hurries you past the moment you''d stop and check.','No company name and no tracking number. A real notice would have both.']::text[], 'Fake delivery texts are among the most common scams going, because nearly everyone has a parcel on the way at some point. The fee is small on purpose. The goal is your card number.', 'draft', '[{"quote":"$1.99 redelivery fee","note":"Delivery companies don''t text you asking for a fee. The small amount is there to get your card number."},{"quote":"within 24 hrs","note":"The deadline hurries you past the moment you''d stop and check."},{"quote":"Parcel Notice","note":"No company name and no tracking number. A real notice would have both."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['If I''m expecting something, I''ll check the tracking number on the shop''s own website.','I won''t tap a link in a text to pay a fee.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A text asking you to pay a fee to redeliver a parcel","The text arriving during the day","The word ''package''"],"correct":0,"affirm":"That''s right. A delivery company won''t text you asking for a fee, so that alone is enough to delete it.","gently":"Understandable, but the clearest sign is the fee. A delivery company won''t text asking for money to try again."}'::jsonb, '/scam-alerts/scams-targeting-seniors-2026'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('prize-processing-fee','Sweepstakes win with a fee','prize') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 1, null, 'CONGRATS! Your number was selected to win $850,000 in our national sweepstakes. Reply CLAIM to receive your winnings. A small processing fee applies.', 'Paying a fee to collect a prize is the core of the prize scam.', array['You can''t win a contest you never entered.','Real prizes don''t cost money to collect. Paying to receive money is the scam.','Replying tells them your number is answered by a real person, and the next message asks for money.']::text[], 'Prize texts have one request at their heart, which is to send a little money to receive a lot. Replying to them also marks your number as one a person answers, which brings more scam texts.', 'draft', '[{"quote":"Your number was selected","note":"You can''t win a contest you never entered."},{"quote":"A small processing fee applies","note":"Real prizes don''t cost money to collect. Paying to receive money is the scam."},{"quote":"Reply CLAIM","note":"Replying tells them your number is answered by a real person, and the next message asks for money."}]'::jsonb, '{"reply_keywords":["claim"]}'::jsonb, 'generic', null, 'human', array['If I didn''t enter, I didn''t win, so I''ll delete it.','I won''t reply to a text from a number I don''t know.','I won''t pay anything to collect a prize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The capital letters","Winning a contest you never entered, with a fee to collect","The amount of money"],"correct":1,"affirm":"Yes. A contest you didn''t enter and a fee to collect are the giveaway.","gently":"Those stand out too, but the clearest sign is winning something you never entered, and being asked to pay to collect it."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('tech-support-virus-alert','Virus warning with a phone number','tech_support') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 1, null, 'SECURITY ALERT: 5 viruses detected on your device. Your banking info may be exposed. Call a certified technician now or tap to fix: {link} Do NOT turn off your phone.', 'Unsolicited virus warnings that push you to contact a technician are tech support scams.', array['Nobody can see viruses on your phone from the outside and text you about them.','Turning it off is safe. This line is there to keep you anxious.','The ''technician'' wants remote access to your device, then payment or your bank login.']::text[], 'Tech support scams start with a scare and end with someone connected to your device. Real security software doesn''t text you a number to call.', 'draft', '[{"quote":"5 viruses detected on your device","note":"Nobody can see viruses on your phone from the outside and text you about them."},{"quote":"Do NOT turn off your phone","note":"Turning it off is safe. This line is there to keep you anxious."},{"quote":"Call a certified technician now","note":"The ''technician'' wants remote access to your device, then payment or your bank login."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll delete the text and won''t call or tap anything in it.','If I''m worried about my phone, I''ll ask someone I know or visit the store where I bought it.','I won''t let anyone I didn''t contact first connect to my phone or computer.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A text claiming it can see viruses on your phone","The word ''certified''","Being told not to turn the phone off"],"correct":0,"affirm":"That''s it. Nobody can see what''s on your phone from outside and text you about it.","gently":"That line is meant to scare you, so it''s a good one to notice. The first sign, though, is the claim itself: nobody can see your phone''s contents from outside."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-account-locked','Bank account locked','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 1, null, 'Your Bank Alert: unusual sign-in detected. Your account has been locked. Verify your card number and PIN within 12 hrs to unlock: {link}', 'Your bank never asks for your PIN or card number by text.', array['Your real bank uses its own name and usually your name too.','No bank ever asks for your PIN, by text or any other way.','The deadline is there to rush you.']::text[], 'Account-locked texts work because they make your money feel in danger and offer a quick fix. If something really were wrong, calling the number on your card would tell you.', 'draft', '[{"quote":"Your Bank Alert","note":"Your real bank uses its own name and usually your name too."},{"quote":"card number and PIN","note":"No bank ever asks for your PIN, by text or any other way."},{"quote":"within 12 hrs","note":"The deadline is there to rush you."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll call the number on the back of my card and ask if anything''s wrong.','I''ll sign in the way I always do, never from a link in a text.','I''ll never give my PIN to anyone.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions unusual sign-in activity","It asks for your card number and PIN","It came by text"],"correct":1,"affirm":"Yes. A bank will never ask for your PIN, so that request alone gives it away.","gently":"Real banks do mention unusual activity sometimes, which is why this is convincing. The giveaway is the request for your PIN."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('utility-shutoff-today','Power shut-off today','utility') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 2, null, 'FINAL NOTICE: your electric service will be disconnected TODAY at 4PM for a past-due balance of $186.42. To avoid shut-off, pay now by gift card or online: {link}', 'Same-day shut-off threats and gift card payments are utility scam signs.', array['Utilities send written notices over weeks before any shut-off. Same-day warnings by text are made up.','No utility takes gift cards. Anyone asking for one is running a scam.','Calling it final when you''ve had no earlier notice is a pressure trick.']::text[], 'Utility scams lean on the worry of being without power. Real utilities give plenty of written notice and take ordinary payments.', 'draft', '[{"quote":"disconnected TODAY at 4PM","note":"Utilities send written notices over weeks before any shut-off. Same-day warnings by text are made up."},{"quote":"by gift card","note":"No utility takes gift cards. Anyone asking for one is running a scam."},{"quote":"FINAL NOTICE","note":"Calling it final when you''ve had no earlier notice is a pressure trick."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll call the number on my last paper bill and ask about my account.','I''ll never pay a bill with a gift card.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The exact dollar amount","Being asked to pay by gift card","The 4PM time"],"correct":1,"affirm":"Right. No utility takes gift cards, so that request gives it away.","gently":"The exact amount is meant to look official. The surest sign is the gift card: no utility takes them."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('jury-duty-warrant','Missed jury duty fine','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 2, null, 'County Court Notice: you failed to appear for jury duty and a warrant may be issued. Pay the $495 fine today to cancel it: {link}', 'Courts don''t threaten arrest or collect fines by text.', array['Courts don''t threaten arrest by text. A missed summons is handled by post.','Courts don''t take fines through text links, and paying never cancels a warrant.','It doesn''t say which county or court. A real notice would.']::text[], 'Jury duty scams work on worry and embarrassment. You can always call the clerk''s office yourself, using a number you looked up.', 'draft', '[{"quote":"a warrant may be issued","note":"Courts don''t threaten arrest by text. A missed summons is handled by post."},{"quote":"Pay the $495 fine today to cancel it","note":"Courts don''t take fines through text links, and paying never cancels a warrant."},{"quote":"County Court Notice","note":"It doesn''t say which county or court. A real notice would."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll look up the court''s number myself and call to ask.','I won''t pay a fine from a link in a text.','I''ll tell someone in the family, since these scams count on embarrassment.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to pay a fine by text to cancel a warrant","The word ''County''","The text arriving during the day"],"correct":0,"affirm":"Yes. Courts don''t take payment by text to make a warrant go away.","gently":"Official-sounding words are part of the disguise. The clearest sign is the payment request."}'::jsonb, '/scam-alerts/scams-targeting-seniors-2026'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('family-new-email','"It''s me" from a new number','family_emergency') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 2, null, 'Hi it''s me, I lost my phone so this is my new number. I''m in a bit of trouble and need $600 today. Please don''t tell Mom or Dad yet. Can you help? Reply YES and I''ll explain', '"It''s me" texts from a new number asking for urgent, secret money are family emergency scams.', array['Someone you know would use their name. ''It''s me'' lets you fill in who you think it is.','A new number stops you from calling the old one to check, which is exactly what to do.','Keeping it secret keeps you from hearing that everyone is fine.']::text[], 'This is the text version of the grandparent scam, and it works because it lands on love and worry at once. Calling the number you already have settles it in a minute.', 'draft', '[{"quote":"Hi it''s me","note":"Someone you know would use their name. ''It''s me'' lets you fill in who you think it is."},{"quote":"this is my new number","note":"A new number stops you from calling the old one to check, which is exactly what to do."},{"quote":"Please don''t tell Mom or Dad yet","note":"Keeping it secret keeps you from hearing that everyone is fine."}]'::jsonb, '{"reply_keywords":["yes","what happened","ok"]}'::jsonb, 'generic', null, 'human', array['I''ll call them on the number I already have.','If I can''t reach them, I''ll call someone else in the family before I send anything.','I won''t send money because of a text from a new number.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A new number, no name, and a request to keep it secret","The amount of $600","The text being friendly"],"correct":0,"affirm":"Exactly. No name, a new number and a secret are how these keep you from checking.","gently":"The amount can feel small, which is part of the trick. The clearest sign is the new number with no name and the request for secrecy."}'::jsonb, '/scam-alerts/ai-voice-cloning-grandparent-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('charity-disaster-match','Disaster relief with a matching deadline','charity') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 2, null, 'Storm Relief Fund: families lost everything this week. Gifts are DOUBLED until midnight! Give $50 by gift card or wire, it reaches them fastest: {link}', 'Fake charities use deadlines and untraceable payment methods.', array['Real charities welcome gifts any time. A countdown stops you from looking the charity up first.','Established charities take cards and checks. Gift cards and wires can''t be traced or refunded.','A name that sounds right but that you''ve never heard of is worth looking up before giving.']::text[], 'Fake charities appear after every disaster because generous people want to help fast. Giving through a charity you know, on its own website, gets your money where it should go.', 'draft', '[{"quote":"DOUBLED until midnight","note":"Real charities welcome gifts any time. A countdown stops you from looking the charity up first."},{"quote":"by gift card or wire","note":"Established charities take cards and checks. Gift cards and wires can''t be traced or refunded."},{"quote":"Storm Relief Fund","note":"A name that sounds right but that you''ve never heard of is worth looking up before giving."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll give to a charity I already know, on its own website.','I''ll look up any charity I don''t know before giving.','I won''t give by gift card or wire.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions storms","Asking for gift cards or a wire","Suggesting $50"],"correct":1,"affirm":"Yes. Real charities don''t ask for gift cards or wires.","gently":"Mentioning real news is what makes these convincing. The clearest sign is the payment method."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('medicare-plan-change','Medicare plan ending','medicare') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Medicare Benefits Office: your 2027 coverage has been flagged for changes. To avoid a gap in coverage, confirm your Medicare number within 48 hrs: {link}', 'Medicare doesn''t text asking for your Medicare number.', array['Open Enrollment runs for weeks. Nobody official gives you 48 hours.','Your Medicare number is used to bill for things you never got. Keep it for your doctors and pharmacy.','Medicare doesn''t text you to ask for your number.']::text[], 'This is harder because it arrives during real Open Enrollment, when you expect news about your plan. The short deadline and the request for your number give it away.', 'draft', '[{"quote":"within 48 hrs","note":"Open Enrollment runs for weeks. Nobody official gives you 48 hours."},{"quote":"confirm your Medicare number","note":"Your Medicare number is used to bill for things you never got. Keep it for your doctors and pharmacy."},{"quote":"Medicare Benefits Office","note":"Medicare doesn''t text you to ask for your number."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', '2026-12-08'::timestamptz, 'human', array['I''ll call the number on my Medicare card if I want to check my plan.','I won''t type my Medicare number into a link from a text.','I''ll review plans with someone I trust, like a local SHIP counselor.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions next year''s coverage","A request for your Medicare number with a 48-hour deadline","It came in the autumn"],"correct":1,"affirm":"That''s right. A short deadline plus a request for your Medicare number is the combination to watch for.","gently":"It feels more believable because of the timing. The giveaway is the deadline and the request for your number."}'::jsonb, '/scam-alerts/medicare-open-enrollment-scams'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('tax-refund-pending','Tax refund waiting','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Tax Refund Dept: you are eligible for an additional refund of $1,284.00. Confirm your bank details and SSN to receive it by direct deposit: {link}', 'The tax agency doesn''t text about refunds or ask for your Social Security number.', array['The tax agency contacts people by post, not by text, and not to hand out surprise money.','Together these let someone take over accounts or file a return in your name.','No real agency signs a text this way.']::text[], 'Good news can lower your guard, which is why refund texts work for some people. The request for your bank details and Social Security number is what to notice.', 'draft', '[{"quote":"you are eligible for an additional refund","note":"The tax agency contacts people by post, not by text, and not to hand out surprise money."},{"quote":"your bank details and SSN","note":"Together these let someone take over accounts or file a return in your name."},{"quote":"Tax Refund Dept","note":"No real agency signs a text this way."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['If I think I''m owed a refund, I''ll check on the tax agency''s website by typing the address myself.','I''ll never send my Social Security number in reply to a text.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The refund amount","Being asked for your bank details and Social Security number by text","The word ''direct deposit''"],"correct":1,"affirm":"Yes. Nobody official asks for those by text.","gently":"The exact amount is there to seem believable. The clearest sign is the request for your Social Security number and bank details."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('subscription-renewal-refund','Surprise renewal charge','tech_support') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Billing Support: your Device Protection Plan renewed for $399.99. If you did not authorize this, reply REFUND within 24 hrs and an agent will call you.', 'Fake renewal notices push you to ''cancel'' through a scammer.', array['If you don''t recognize the plan, that''s because there isn''t one. The surprise sends you straight to them.','The rush makes you act before checking your real statement.','The ''refund'' call ends with someone on your computer or in your bank account.']::text[], 'Fake receipts make you want to act to protect yourself, and that urge is the trap. Your real statement will tell you whether anything was charged.', 'draft', '[{"quote":"Device Protection Plan","note":"If you don''t recognize the plan, that''s because there isn''t one. The surprise sends you straight to them."},{"quote":"reply REFUND within 24 hrs","note":"The rush makes you act before checking your real statement."},{"quote":"an agent will call you","note":"The ''refund'' call ends with someone on your computer or in your bank account."}]'::jsonb, '{"reply_keywords":["refund","no","i did not"]}'::jsonb, 'generic', null, 'human', array['I''ll check my card statement directly for the charge.','If I see a charge I don''t recognize, I''ll call the number on my card.','I won''t reply to a receipt I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["A charge for a plan you never bought, with 24 hours to reply","The amount ending in .99","The word ''agent''"],"correct":0,"affirm":"Right. A charge you don''t recognize with a short window is the setup.","gently":"Prices ending in .99 are normal. The sign is a charge for something you never bought and a rush to respond."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('romance-wrong-address','Friendly stranger, wrong number','romance') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Hello, is this Linda? It''s Daniel from the reunion. Sorry if I have the wrong number. You seem kind anyway. I''m working overseas and it''s been a lonely year since my wife passed.', '"Wrong number" openers from lonely, overseas strangers are how romance scams begin.', array['The ''wrong number'' opener is a way to start chatting with a stranger without looking like a pitch.','Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams.','Working abroad explains why they can never meet, and later why they need money.']::text[], 'Romance scams start slowly and kindly, and money doesn''t come up for weeks. The opening is the best place to spot them, and it follows a familiar pattern.', 'draft', '[{"quote":"Sorry if I have the wrong number","note":"The ''wrong number'' opener is a way to start chatting with a stranger without looking like a pitch."},{"quote":"it''s been a lonely year since my wife passed","note":"Sharing a loss straight away builds sympathy fast. It''s a common opening in romance scams."},{"quote":"I''m working overseas","note":"Working abroad explains why they can never meet, and later why they need money."}]'::jsonb, '{"reply_keywords":["wrong number","sorry","hello","hi"]}'::jsonb, 'generic', null, 'human', array['I won''t keep chatting with someone who texted me by mistake.','I''ll block numbers I don''t know that try to start a conversation.','I''ll never send money to someone I haven''t met in person.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The name Linda","A stranger texting ''by mistake'', sharing a loss and living overseas","Being polite"],"correct":1,"affirm":"Yes. That pattern is how these usually begin.","gently":"Politeness is part of the charm. The pattern to notice is the wrong-number start, the shared loss and the job overseas."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('voter-registration-problem','Voter registration problem','election') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Election Records Office: a problem with your voter registration may stop you voting this year. Confirm your DOB and last 4 of SSN to stay registered: {link}', 'Election offices don''t text asking for your Social Security number to keep you registered.', array['Election offices send problems by post, and you can check your registration on your state''s official website.','Nobody needs your Social Security number by text to keep you registered.','The threat of losing your vote is there to make you act fast.']::text[], 'Election scams pick up before a vote, when people care most about taking part. Checking your own registration takes a couple of minutes and is far safer than any link.', 'draft', '[{"quote":"a problem with your voter registration","note":"Election offices send problems by post, and you can check your registration on your state''s official website."},{"quote":"last 4 of SSN","note":"Nobody needs your Social Security number by text to keep you registered."},{"quote":"may stop you voting this year","note":"The threat of losing your vote is there to make you act fast."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', '2026-11-04'::timestamptz, 'human', array['I''ll check my registration on my state''s official election website.','I''ll call my county election office if I''m unsure.','I won''t give personal details through a link in a text.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions voting this year","It asks for part of your Social Security number by text","It names an election office"],"correct":1,"affirm":"Right. No election office asks for that by text.","gently":"The timing makes it feel real. The clearest sign is the request for part of your Social Security number."}'::jsonb, '/scam-alerts/weekly-2026-10-19'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('benefits-suspended','Benefits suspended','government') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Benefits Administration: your monthly benefits are SUSPENDED due to suspicious activity on your SSN. Call your case officer today to reinstate: {link} Case BA-2207-44', 'Benefits aren''t suspended by text.', array['A Social Security number can''t be suspended, and benefits aren''t stopped by text.','The ''case officer'' is the scammer.','A reference number makes it look official. Anyone can make one up.']::text[], 'Government impersonation takes a real worry, losing income you rely on, and dresses it up with official-sounding details. A call to the agency on a number you found yourself clears it up.', 'draft', '[{"quote":"suspicious activity on your SSN","note":"A Social Security number can''t be suspended, and benefits aren''t stopped by text."},{"quote":"Call your case officer today","note":"The ''case officer'' is the scammer."},{"quote":"Case BA-2207-44","note":"A reference number makes it look official. Anyone can make one up."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll call the agency on a number I look up myself.','I''ll check my benefits by signing in the usual way.','I won''t call a ''case officer'' named in a text.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The case number","A text saying your benefits are suspended over your Social Security number","The word ''monthly''"],"correct":1,"affirm":"Yes. Benefits aren''t suspended by text, so the claim itself gives it away.","gently":"The case number is there to feel official. The giveaway is the claim itself."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('customs-duty-package','Customs fee on a package','delivery') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Intl Shipping Customs: shipment 7740-2219-US is held pending import duty of $12.60. Pay within 3 days or a storage fee applies: {link}', 'Surprise customs fees by text are a variation on the delivery fee scam.', array['Shops and carriers tell you about duties at checkout or on delivery, not in a surprise text.','A small, exact amount feels routine. The real aim is your card number.','Adding a penalty is another way to hurry you.']::text[], 'This is a close cousin of the redelivery fee scam, with a shipment number to look official. Most people don''t know how customs fees work, which is what makes it believable.', 'draft', '[{"quote":"held pending import duty","note":"Shops and carriers tell you about duties at checkout or on delivery, not in a surprise text."},{"quote":"$12.60","note":"A small, exact amount feels routine. The real aim is your card number."},{"quote":"a storage fee applies","note":"Adding a penalty is another way to hurry you."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll check the order on the shop''s own website if I''m expecting something.','I won''t pay a customs fee from a link in a text.','I''ll delete it.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The shipment number","A surprise text asking for a customs fee through a link","Three days to pay"],"correct":1,"affirm":"Right. A surprise fee through a link is the sign.","gently":"The shipment number is there to look official. The clearest sign is the surprise fee through a link."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('shared-document-sign-in','Shared photos sign-in','account_takeover') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 3, null, 'Someone shared "Family Photos 2026" with you. Sign in with your email and password to view them: {link} Link expires in 48 hrs.', 'Fake shared-photo texts collect email passwords.', array['A sign-in page reached from a text link is how passwords are collected. Your email password unlocks your other accounts.','A real share says who it''s from. ''Someone'' keeps it vague so you''ll assume it''s family.','A personal-sounding file name is bait.']::text[], 'Whoever has your email password can reset nearly every other password you have. Asking the person who supposedly sent it is the quickest check.', 'draft', '[{"quote":"Sign in with your email and password","note":"A sign-in page reached from a text link is how passwords are collected. Your email password unlocks your other accounts."},{"quote":"Someone shared","note":"A real share says who it''s from. ''Someone'' keeps it vague so you''ll assume it''s family."},{"quote":"Family Photos 2026","note":"A personal-sounding file name is bait."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['If I''m expecting photos, I''ll ask the person directly whether they sent them.','I won''t type my email password into a page I reached from a text.','If I already did, I''ll change my password and ask someone to help.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It mentions photos","It doesn''t say who shared it and asks for your email password","The 48-hour limit"],"correct":1,"affirm":"Yes. A vague ''someone'' and a request for your password is the pattern.","gently":"The details make it feel personal. The sign is that it doesn''t say who, then asks for your password."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('bank-safe-account','Bank fraud team and a "safe account"','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 4, null, 'Fraud Prevention: following up on this morning''s alert. A branch employee may be involved in fraud on your account. Reply YES and we''ll call to help you move your savings to a secure account. Don''t discuss with branch staff.', 'Banks never ask you to move money to a ''safe account'' or keep it from branch staff.', array['Pretending to continue an earlier conversation makes you think you''ve already checked.','A real bank never asks you to move money to keep it safe.','Branch staff would tell you it''s a scam. That''s why they don''t want you talking to them.']::text[], 'The ''safe account'' scam is one of the most expensive, because people move savings believing they''re protecting them. Any request to move money to keep it safe is the scam.', 'draft', '[{"quote":"following up on this morning''s alert","note":"Pretending to continue an earlier conversation makes you think you''ve already checked."},{"quote":"move your savings to a secure account","note":"A real bank never asks you to move money to keep it safe."},{"quote":"Don''t discuss with branch staff","note":"Branch staff would tell you it''s a scam. That''s why they don''t want you talking to them."}]'::jsonb, '{"reply_keywords":["yes","call me","ok"]}'::jsonb, 'generic', null, 'human', array['I''ll call the number on the back of my card.','I''ll never move money to a ''secure account'' for anyone.','I''ll tell someone in the family before I move any money.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being asked to move savings and not tell branch staff","Being told about a fraud alert","The text arriving in the morning"],"correct":0,"affirm":"Exactly. Moving money to keep it safe, kept from the branch, is the scam.","gently":"Real banks do send fraud alerts, which is why this works. The giveaway is moving your savings and keeping it from the branch."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('order-shipped-unknown-address','Order shipped to a strange address','shopping') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 4, null, 'Order #114-3920-5581 shipped: 65" Smart TV, $1,149.00, to 2290 Lakeview Dr Apt 4B. Not you? Reply NO to cancel and speak with support.', 'Fake order alerts use alarm about a stranger''s purchase to reach a fake support line.', array['A strange address makes you worry someone is using your account, so you reply to fix it.','This is the hook. ''Support'' turns out to be the scammer.','A large purchase you didn''t make is meant to alarm you into acting fast.']::text[], 'This looks like ordinary order texts, which is why it''s rated hard. The way to check is the same as always: go to the shop yourself.', 'draft', '[{"quote":"to 2290 Lakeview Dr Apt 4B","note":"A strange address makes you worry someone is using your account, so you reply to fix it."},{"quote":"Not you? Reply NO","note":"This is the hook. ''Support'' turns out to be the scammer."},{"quote":"$1,149.00","note":"A large purchase you didn''t make is meant to alarm you into acting fast."}]'::jsonb, '{"reply_keywords":["no","not me","cancel order"]}'::jsonb, 'generic', null, 'human', array['I''ll open the shop''s app or website myself and look at my orders.','I''ll check my card statement for the charge.','I won''t reply to an order text I don''t recognize.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["The order number","An order you didn''t place, with an easy way to ''cancel'' by replying","The price of the TV"],"correct":1,"affirm":"Yes. An order you didn''t make with a convenient reply option is the setup.","gently":"The order number looks real, which is what makes this convincing. The sign is an order you didn''t place with an easy ''cancel'' that reaches them."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('patient-portal-message','New message from your care team','health') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 5, null, 'You have a new secure message from your care team about your recent visit, which may include test results. Sign in to the patient portal to read it: {link}', 'Look-alike portal notices collect sign-in details; open the portal yourself.', array['Test results are something everyone wants to read straight away. The text never names your doctor or clinic.','The link leads to a look-alike sign-in page. Open the portal the way you usually do.','A real notice usually names the practice. ''Your care team'' could be anyone.']::text[], 'This is the hardest kind, because it''s nearly identical to a real notice. If you always open the portal yourself, the link never matters.', 'draft', '[{"quote":"which may include test results","note":"Test results are something everyone wants to read straight away. The text never names your doctor or clinic."},{"quote":"Sign in to the patient portal","note":"The link leads to a look-alike sign-in page. Open the portal the way you usually do."},{"quote":"your care team","note":"A real notice usually names the practice. ''Your care team'' could be anyone."}]'::jsonb, '{"reply_keywords":[]}'::jsonb, 'generic', null, 'human', array['I''ll open the patient portal from my own bookmark or the clinic''s website.','If I''m not sure, I''ll call my doctor''s office.','I''ll notice when a message doesn''t name my doctor or clinic.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["It doesn''t name your doctor or clinic","It mentions test results","It came by text"],"correct":0,"affirm":"Well spotted. Without a name, it could be from anyone.","gently":"Real portals mention results too, so this one is genuinely hard. The small sign is that it never names your doctor or clinic."}'::jsonb, null
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
with scam as (insert into public.practice_scams(stable_code,name,category) values('phantom-hacker-federal','Hacker warning and a federal agent','bank') on conflict(stable_code) do update set stable_code=excluded.stable_code returning id)
insert into public.practice_scam_versions(scam_id,version_number,format,difficulty,subject,content,learning_objective,warning_signs,debrief,status,tells,channel_variant,brand_mode,expires_at,generated_by,next_steps,question,context_url)
select scam.id, coalesce((select max(version_number) from public.practice_scam_versions v where v.scam_id=scam.id),0)+1, 'text', 5, null, 'Customer Protection: your computer was accessed by an overseas group and your bank and retirement accounts may be at risk. A federal agent will call today to secure your funds. Keep this confidential, including from family.', 'The ''phantom hacker'' scam chains a tech scare, a fake bank and a fake agent to move savings.', array['Government agencies never call to help move your money.','Secrecy from family is the biggest warning sign of all.','A frightening claim you can''t check is how this scam begins.']::text[], 'This is a version of what the FBI calls the phantom hacker scam. It plays out in stages, each making the next more believable. Telling family is what breaks the chain.', 'draft', '[{"quote":"A federal agent will call today to secure your funds","note":"Government agencies never call to help move your money."},{"quote":"Keep this confidential, including from family","note":"Secrecy from family is the biggest warning sign of all."},{"quote":"your computer was accessed by an overseas group","note":"A frightening claim you can''t check is how this scam begins."}]'::jsonb, '{"reply_keywords":["ok","yes","what should i do","when"]}'::jsonb, 'generic', null, 'human', array['I''ll tell someone in the family straight away, whatever I''ve been asked.','I won''t move money because of a call or text, even from someone who says they''re from the government.','I''ll call my bank on the number on my card.']::text[], '{"prompt":"If this had been real, what would have been the first sign it wasn''t?","choices":["Being told to keep it from family and wait for an agent to handle your money","The word ''overseas''","It came by text"],"correct":0,"affirm":"Yes. Secrecy from family and an ''agent'' for your money give it away.","gently":"The scary details are there to rush you. The clearest signs are the secrecy and the agent who''ll help with your money."}'::jsonb, '/scam-alerts/phantom-hacker-gold-courier-scam'
from scam where not exists(select 1 from public.practice_scam_versions v where v.scam_id=scam.id and v.format='text');
commit;
